ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"status": 200,
	"code": "OK",
	"response": {
		"createOrderRequestResponse": {
			"return": {
				"WSResponseHeader2": {
					"System": {
						"name": "Mulesoft",
						"correlationID": attributes.headers.'x-correlation-id',
						"processingServer": "Mulesoft"
					},
					"Service": {
						"status": "PASS",
						"responseDate": (now() >> "America/Bogota") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS"},
						"statusDetail": {
							"errorCode": 0,
							"errorMessage": "El MSG se proceso Correctamentamente"
						}
					}
				},
				"CrearOrdenIn": {
					"recibido": true
				}
			}
		}
	}
}

%dw 2.0
output application/json
var inputMessage = payload.wsInputCreateDispatchOrder.parameters.wsInputCreateDispatchOrder
---
{
  "createOrderRequest": {
    "createOrderIn": {
      "order": {
        "cunNumber": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.cunNumber as String,
        "reference": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.reserveNumber default "",
        "date": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.date,
        "resend": {
          "dispatchOrder": inputMessage.wsRequestHeader.property[0].REENVIO default 'false' ,
          "quantity": if (inputMessage.wsRequestHeader.property[0].REENVIO == 'True') inputMessage.wsRequestHeader.property[0].INTENTOS as Number else 0 
        },
        "orderType": inputMessage.wsRequestHeader.property[0].TIPOORDEN,
        "entryType": inputMessage.wsRequestHeader.property[0].TIPOENTREGA default "",
        "observations": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.clientObservations default "",
        "collection": {
          "required": if (inputMessage.wsRequestHeader.property[0].RECAUDO == 'True') true else false,
          "value": if (inputMessage.wsRequestHeader.property[0].RECAUDO == 'True') inputMessage.wsRequestHeader.property[0].VALORRECAUDO as Number else 0 
        },
        "address": {
          "address": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.address,
          "district": inputMessage.wsRequestHeader.property[0].BARRIO default "",
          "city": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.city as String,
          "department": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.department as String
        },
        "contact": {
          "names": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.names,
          "surnames": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.surnames,
          "documentType": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.documentType,
          "documentNumber": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.documentNumber as String,
          "mobilePhone": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.mobileNumber as String,
          "mobilePhone2": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.mobileNumber2 as String default "",
          "phoneNumber": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.phoneNumber as String default "",
          "email": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.email default ""
        },
        "item": {
          "store": inputMessage.inputCreateDispatchOrder.dispatchOrderHeader.callCenter,
          "material": inputMessage.inputCreateDispatchOrder.dispatchOrderDetail[0].dispatchOrderCode.partNumber,
          "type": "SIMCard",
          "subType": inputMessage.wsRequestHeader.property[0].SUBTIPO,
          "name": inputMessage.wsRequestHeader.property[0].NOMBRE,
          "campaign": inputMessage.wsRequestHeader.property[0].CAMPANA,
          "value": inputMessage.inputCreateDispatchOrder.dispatchOrderDetail[0].dispatchOrderCode.equipmentValue,
          "quantity": inputMessage.inputCreateDispatchOrder.dispatchOrderDetail[0].dispatchOrderCode.quantity
        }
      }
    }
  }
}
